function SAMPLE(u0, log_target, T):
    u <- u0;  lp <- log_target(u)
    repeat T times:
        pick i != i' in rows, j != j' in cols, sign s in {+1,-1}
        w <- u + s * B(i, i', j, j')
        if w has a negative entry: continue
        wp <- log_target(w)
        if wp >= lp or rand() < exp(wp - lp):
            u <- w;  lp <- wp
    return u

